const input = document.querySelector('#todoInput');
const addButton = document.querySelector('#add');
const clearButton = document.querySelector('#clearButton');
const list = document.querySelector('#mylist');

function addElement() {
  const text = input.value.trim();
  if (!text) return;

  const row = document.createElement('div');
  const checkbox = document.createElement('input');
  const label = document.createElement('label');

  checkbox.type = 'checkbox';
  label.innerText = text;
  checkbox.addEventListener('click', () => row.remove());
  row.addEventListener('dblclick', () => row.remove());
  row.append(checkbox, label);
  list.appendChild(row);
  input.value = '';
}

function emptyList() {
  while (list.firstChild) list.removeChild(list.firstChild);
}

addButton.addEventListener('click', addElement);
input.addEventListener('keydown', event => {
  if (event.key === 'Enter') addElement();
});
clearButton.addEventListener('click', emptyList);

const form = document.querySelector('#registrationForm');
const message = document.querySelector('#msg');

form.addEventListener('submit', function (event) {
  const issues = [];
  const name = document.getElementsByName('fname')[0].value;
  const email = document.getElementsByName('email')[0].value;
  const mobile = document.getElementsByName('mobile')[0].value;
  const source = document.querySelector("input[name='aboutus']:checked")?.value;

  if (!isFilled(name)) issues.push('First name is missing');
  else if (!isName(name)) issues.push('Name must be 2-100 English letters');

  if (!isFilled(email)) issues.push('Email is missing');
  if (!isEmail(email)) issues.push('Email format is wrong');

  if (!isFilled(mobile)) issues.push('Mobile is missing');
  if (!isMobile(mobile)) issues.push('Mobile must contain 9 digits');

  if (!isWhitelisted(source)) issues.push('Selection is invalid');

  if (issues.length) {
    event.preventDefault();
    message.innerText =
      'Issues found [' + issues.length + ']: ' + issues.join(', ');
  }
});

const isFilled = value => value.trim().length > 0;
const isName = value => /^[A-Za-z]{2,100}$/.test(value);
const isEmail = value => /^[a-z0-9]+@[a-z]+\.[a-z]{2,4}$/i.test(value);
const isMobile = value => /^[0-9]{9}$/.test(value);
const isWhitelisted = value => ['Google', 'TV', 'Friend'].includes(value);

